from pathlib import Path
import json,shutil,html,hashlib
ROOT=Path(__file__).resolve().parents[1];source=ROOT/'reports/quality';out=ROOT/'docs/samples/quality';out.mkdir(parents=True,exist_ok=True);metrics=json.loads((source/'metrics.json').read_text());cards=[]
for mode,name in [('escape','Ring Escape'),('multiply','Ball Multiplication'),('last','Last Ball Standing')]:
 parts=[]
 for version,label in [('before','改修前'),('after','改修後')]:
  movie=source/version/(mode+'.mp4');target=out/(mode+'-'+version+'.mp4');shutil.copyfile(movie,target);digest=hashlib.sha256(target.read_bytes()).hexdigest()[:12];image=out/(mode+'-'+version+'.png');shutil.copyfile(source/version/(mode+'-7.png'),image)
  parts.append(f'<div><h3>{label}</h3><video playsinline controls preload="none" poster="{image.name}" src="{target.name}?v={digest}"></video><a download href="{target.name}?v={digest}">MP4を保存</a></div>')
 m=next(m for m in metrics['results'] if m['mode']==mode);new=json.loads((source/'after'/(mode+'.json')).read_text());old=json.loads((source/'before'/(mode+'.json')).read_text());cards.append('<section><h2>'+name+'</h2><div class="pair">'+''.join(parts)+'</div><p>'+html.escape(f"結果: {m['outcome']} / A/V残差 {m['audio_timeline_residual_seconds']*1000:.1f}ms（1ms音声・4.17ms映像照合の刻み）/ 実測平均 {m['encoded_average_fps']:.1f}fps / 動作区間の最大フレーム間隔 {m['max_active_frame_gap_seconds']*1000:.1f}ms / 衝突計算打切り {m['physics']['budgetStops']}")+'</p></section>')
shutil.copyfile(source/'metrics.json',out/'metrics.json');shutil.copyfile(source/'audit-repro.json',out/'audit-repro.json')
(out/'index.html').write_text('<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QUALITY OVERHAUL — before / after</title><style>body{background:#0b1220;color:#edf6ff;font:16px system-ui;margin:24px auto;padding:0 18px;max-width:1100px}h1{font-size:30px}h3{color:#8ef0cf}.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}section{background:#131e30;padding:20px;margin:24px 0;border-radius:16px}video{width:100%;max-height:75vh;background:#050910}a{color:#9cf5d5;display:inline-block;padding:12px 0}p{line-height:1.8;overflow-wrap:anywhere}@media(max-width:600px){.pair{grid-template-columns:1fr}body{margin-top:16px}}</style><a href="../../">アプリへ戻る</a><h1>完成度を、実際の動画で比べる。</h1><p>全6本を実際に録画。共通入力：720×1280、シード10、15秒、効果音ON・BGMなし。録画方式の開始待ちによりファイル長は約15.1秒です。物理モデル・配置・初期半径・ルール・演出は改善対象のため同一ではなく、改修前の状態への完全な一変数実験ではありません。改修後は60fps取り込みを目標とし、再圧縮では元録画のフレーム数を保存します。重複フレームを挿入してFPSを増やしません。</p><p>新作・テンプレート数は増やしていません。初期配置は非重複、すり抜け対策は移動経路の接触時刻を計算。回転端点は細分化された時間内の線形近似です。終端0.8秒は測定結果カードを表示し、成功を捏造せず未達ならTIME UPを表示します。</p><p>音声はイベント時刻から事前合成し、MP4と同期した時刻原点で再生。旧版とは音量も変更しているため、比較時は再生音量にも注意してください。衝突音の聴感や人気、収益は自動評価していません。Safari実機・長時間高負荷・全設定は未検証のため量産は停止中です。</p>'+''.join(cards)+'<a href="metrics.json">測定結果JSON</a> · <a href="audit-repro.json">旧版の問題の再現データ</a><p>残る制約：MediaRecorderは可変フレーム間隔です。厳密な固定60fpsではなく、ブラウザと端末に依存したフレーム間隔が残ります。公開検査はChrome、実際のiPhoneの保存・音・共有・熱は未検証です。元のSNS動画を視聴できないため「人気作品と同品質」を保証しません。ご自身で前後動画を再生して判断してください。</p></html>')
